	[ 'eans' => [ '4016432466044' ], 'html' => '<p>Dehydrator fra Gastroback i den kompakte udgave Design Mini Professional, 28,2 × 34,7 × 20,6 cm. Den tørrer mindre portioner frugt, urter og kød og fylder lidt på bordet – til køkkener, hvor pladsen er knap.</p><ul><li>Mål: 28,2 × 34,7 × 20,6 cm</li><li>Kompakt model</li></ul>' ],
