	[ 'eans' => [ '7350101113486' ], 'html' => '<p>Fire skåle fra Marelds Akio-serie med en diameter på 14 cm og 50 cl i hver – størrelsen til misosuppe, ris eller en lille salat. Serien findes også i 21 cm, hvis du vil have større skåle i samme stil.</p><ul><li>Ø 14 cm</li><li>Rumfang: 50 cl</li><li>4 stk.</li></ul>' ],
